<?php $shown = $tab === 'overview' ? array_slice($filteredDocuments, 0, 8) : $filteredDocuments; ?>
<div class="table-wrap desktop-table"><table class="table"><thead><tr><th>Số, ký hiệu</th><th>Tên văn bản</th><th>Loại</th><th>Ngày ban hành</th><th>Đơn vị</th><th></th></tr></thead><tbody><?php if(!$shown):?><tr><td colspan="6"><div class="empty"><i class="bi bi-inbox"></i>Chưa có văn bản phù hợp.</div></td></tr><?php else:foreach($shown as $row):?><tr><td><strong><?=e($row['symbol']??'')?></strong><div class="sub"><?=e($row['field']??'')?></div></td><td><div class="title"><?=e($row['title']??'')?></div><div class="sub"><?=e($row['signer']??'')?></div></td><td><span class="pill"><?=e($row['type']??'')?></span></td><td><?=vb_fmt_date((string)($row['issued_date']??''))?></td><td><?=e($row['issuer']??'')?><div class="sub"><?=e($row['issuer_level']??'')?></div></td><td><a class="btn btn-soft" target="_blank" href="<?=e(vb_file_url((string)($row['file_path']??'')))?>"><i class="bi bi-eye"></i> Xem</a></td></tr><?php endforeach;endif;?></tbody></table></div>
<div class="doc-cards"><?php if(!$shown):?><div class="empty"><i class="bi bi-inbox"></i>Chưa có văn bản phù hợp.</div><?php else:foreach($shown as $row):?><article class="card doc-card"><div class="title"><?=e($row['title']??'')?></div><div class="sub"><?=e($row['symbol']??'')?> · <?=vb_fmt_date((string)($row['issued_date']??''))?></div><div class="meta"><span class="pill"><?=e($row['type']??'')?></span><span class="pill"><?=e($row['field']??'')?></span></div><div class="sub"><?=e($row['issuer']??'')?></div><a class="btn btn-soft" target="_blank" href="<?=e(vb_file_url((string)($row['file_path']??'')))?>"><i class="bi bi-eye"></i> Mở văn bản</a></article><?php endforeach;endif;?></div>
